// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Attacker attacker;

    function setUp() public { c = new SimpleWallet(); attacker = new Attacker(); }

    function testFuzz_property(uint256 fundAmount, uint256 sendValue) public {
        fundAmount = bound(fundAmount, 1, 1 ether);
        sendValue = bound(sendValue, 0, 1 ether);

        vm.deal(address(attacker), 2 ether);
        vm.deal(address(this), fundAmount);
        (bool okFund,) = address(c).call{value: fundAmount}("");
        require(okFund, "funding failed");

        uint256 before = address(c).balance;

        bool sendOk;
        try c.sendMoney(address(attacker), sendValue) {
            sendOk = true;
        } catch {
            sendOk = false;
        }

        vm.deal(address(attacker), 1);
        vm.prank(address(attacker));
        bool attackerWithdrawOk;
        try c.withdrawAll() {
            attackerWithdrawOk = true;
        } catch {
            attackerWithdrawOk = false;
        }

        assertTrue(!attackerWithdrawOk);
    }
}

contract Attacker {
    receive() external payable {}
}
